mapper.select:
SELECT sh.id, sh.homeworkid, sh.studentid, sh.content, sh.filepath, sh.score, sh.comment, sh.status, sh.submittime, sh.gradetime, sh.grading_status, s.studentno, s.studentname, s.classid, ci.classname, h.title as homeworktitle, h.type as homeworktype, h.deadline, c.courseid, c.coursename, c.semester, t.teachername FROM studenthomework sh LEFT JOIN student s ON sh.studentid = s.studentid LEFT JOIN classinfo ci ON s.classid = ci.classid LEFT JOIN homework h ON sh.homeworkid = h.homeworkid LEFT JOIN course c ON h.courseid = c.courseid LEFT JOIN teacher t ON h.teacherid = t.teacherid
AND (s.studentname LIKE CONCAT('%', #{keyword}, '%') OR h.title LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY sh.id DESC LIMIT #{offset}, #{limit}

SELECT sh.id, sh.homeworkid, sh.studentid, sh.content, sh.filepath, sh.score, sh.comment, sh.status, sh.submittime, sh.gradetime, sh.grading_status, s.studentno, s.studentname, s.classid, ci.classname FROM studenthomework sh LEFT JOIN student s ON sh.studentid = s.studentid LEFT JOIN classinfo ci ON s.classid = ci.classid WHERE sh.homeworkid = #{homeworkid}
AND (s.studentname LIKE CONCAT('%', #{keyword}, '%') OR s.studentno LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY s.studentno ASC LIMIT #{offset}, #{limit}

SELECT sh.id, sh.homeworkid, sh.studentid, sh.content, sh.filepath, sh.score, sh.comment, 
       sh.status, sh.submittime, sh.gradetime, sh.grading_status,
       h.title as homeworktitle, h.type as homeworktype, h.deadline,
       c.courseid, c.coursename, c.semester, t.teachername
FROM studenthomework sh
LEFT JOIN homework h ON sh.homeworkid = h.homeworkid
LEFT JOIN course c ON h.courseid = c.courseid
LEFT JOIN teacher t ON h.teacherid = t.teacherid
WHERE sh.studentid = #{studentid}

    AND c.courseid = #{courseid}


    AND c.semester = #{semester}

ORDER BY sh.submittime DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM studenthomework sh
LEFT JOIN homework h ON sh.homeworkid = h.homeworkid
LEFT JOIN course c ON h.courseid = c.courseid
WHERE sh.studentid = #{studentid}

    AND c.courseid = #{courseid}


    AND c.semester = #{semester}

