mapper.select:
SELECT sh.id, sh.homeworkid, sh.studentid, sh.content, sh.filepath, sh.score, sh.comment, 
       sh.status, sh.submittime, sh.gradetime, sh.grading_status,
       s.studentno, s.studentname, s.classid, ci.classname,
       h.title as homeworktitle, h.type as homeworktype, h.deadline,
       c.courseid, c.coursename
FROM studenthomework sh
LEFT JOIN student s ON sh.studentid = s.studentid
LEFT JOIN classinfo ci ON s.classid = ci.classid
LEFT JOIN homework h ON sh.homeworkid = h.homeworkid
LEFT JOIN course c ON h.courseid = c.courseid
WHERE h.teacherid = #{teacherid}

    AND sh.homeworkid = #{homeworkid}


    AND c.courseid = #{courseid}


    AND s.classid = #{classid}


    AND (s.studentname LIKE CONCAT('%', #{keyword}, '%') OR h.title LIKE CONCAT('%', #{keyword}, '%'))


    AND c.semester = #{semester}

ORDER BY sh.submittime DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM studenthomework sh
LEFT JOIN student s ON sh.studentid = s.studentid
LEFT JOIN classinfo ci ON s.classid = ci.classid
LEFT JOIN homework h ON sh.homeworkid = h.homeworkid
LEFT JOIN course c ON h.courseid = c.courseid
WHERE h.teacherid = #{teacherid}

    AND sh.homeworkid = #{homeworkid}


    AND c.courseid = #{courseid}


    AND s.classid = #{classid}


    AND (s.studentname LIKE CONCAT('%', #{keyword}, '%') OR h.title LIKE CONCAT('%', #{keyword}, '%'))


    AND c.semester = #{semester}

SELECT s.studentid, s.studentno, s.studentname, s.classid, ci.classname
FROM student s
JOIN courseclass cc ON s.classid = cc.classid
JOIN homework h ON cc.courseid = h.courseid
JOIN classinfo ci ON s.classid = ci.classid
WHERE h.homeworkid = #{homeworkid}
AND s.studentid NOT IN (
    SELECT studentid FROM studenthomework WHERE homeworkid = #{homeworkid}
)
ORDER BY s.classid, s.studentno

